<?php foreach(ProfileManager::guardians() as $guardian): ?><form method="post" action="/profiles/revoke"><?= csrf_field() ?><input type="hidden" name="guardian" value="<?= e($guardian['id']) ?>"><p><?= e($guardian['name']) ?> <?= e(t('can view your activity report.')) ?></p><button><?= e(t('Remove guardian access')) ?></button></form><?php endforeach; ?>
